import random #like a mod

ducks = random.randint(-10,10) 

print(f"There are {ducks} ducks!")

pens = random.randrange(1,10,2)#this will give you a random number between 1 and 10 but only odd numbers because of the 2 at the end and the middle number is the step which is how many numbers to skip which if you still did not understand it is like a step counter and it will skip every 2 numbers so it will only give you odd numbers so actually the first number is the stater  the seond number is where you end and the 3rd number is how many numbers you skip or do the multiples of.

print(f"I have {pens} pens!")

